let stage=null;
if(hasDom&&assets.gorge){try{const m=await import('./stage3d.js');stage=await m.createStage({canvas,layer,glow:glowLayer,gorge:assets.gorge,W,H,zoom:ZOOM,settings:{get reduced(){return settings.reduced;}}});document.body.classList.add('webgl');}catch(err){console.warn('Three.js scena nije dostupna, koristi se 2D prikaz.',err);stage=null;}}
