function initAudio(){if(!audio)try{audio=new(window.AudioContext||window.webkitAudioContext)();}catch{}audio?.resume();}
function tone(freq,duration=.15,type='sine',gain=.08,end=freq){if(!audio||!audioEnabled||!settings.volume)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),audio.currentTime+duration);g.gain.setValueAtTime(gain*settings.volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function sound(type){if(type==='hit'){tone(110,.13,'triangle',.5,30);tone(480,.06,'sawtooth',.1,90);}else if(type==='parry'){tone(740,.4,'triangle',.3,1400);tone(1110,.5,'sine',.15);}else if(type==='jump')tone(180,.18,'sine',.14,340);else if(type==='magic'){[440,660,880].forEach((f,i)=>setTimeout(()=>tone(f,.6,'sine',.16),i*80));}else if(type==='hurt')tone(130,.22,'sawtooth',.18,45);else if(type==='wine')tone(300,.35,'sine',.22,600);else tone(220,.1,'triangle',.1,150);}
function music(dt){musicClock-=dt;if(musicClock<=0){const notes=[146.83,220,261.63,293.66,329.63,293.66,220,164.81];tone(notes[Math.floor(time/1.7)%notes.length],1.8,'triangle',.025);tone(73.4,2,'sine',.035);musicClock=1.7;}}
function toast(text,duration=3){$('toast').textContent=text;$('toast').classList.add('visible');toastTime=duration;}
