function die(){if(mode!=='play')return;deaths++;mode='dead';$('death').hidden=false;sound('hurt');keys.clear();}
function damage(amount,dir=0){if(p.invuln>0||p.dash>0)return;const factor=(settings.difficulty==='story'?.55:1)*(p.buff>0?.8:1);p.hp-=amount*factor;p.hurt=.22;p.invuln=1;p.vx+=dir*120;shake=settings.reduced?0:7;burst(p.x,p.y-60,'#ff6a50',12);fx('flash','#ff3020',.06);sound('hurt');if(p.hp<=0){p.hp=0;die();}}
